INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62548928', 62548928, 'analyze_legacy', 'Kejaksaan Republik Indonesia', 'central', 'KEJAKSAAN NEGERI SUMEDANG', 'Belanja Outsourcing Petugas Kebersihan, Pengamanan dan Layanan Kantor (untuk 16 pegawai dan 1 Petugas Pengawas) - UMK 2025', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Sumedang (Kab.)', 1155000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PAKET, @ 1155000000 )', 'Belanja Outsourcing Petugas Kebersihan, Pengamanan dan Layanan Kantor (untuk 16 pegawai dan 1 Petugas Pengawas) - UMK 2025', 'Pengadaan penyedia untuk pekerjaan tenaga alih daya petugas kebersihan, pengamanan, Pelayanan Terpadu Satu Pintu/PTSP/Customer Service, supir dan admin pada Kejaksaan Negeri Sumedang untuk sebanyak 16 orang pegawai dan 1 orang Pengawas. Perusahaan harus memiliki legalitas yang lengkap, memiliki pengalaman dalam bidang serupa selama minimal 5 tahun, pernah bekerja sama dengan instansi pemerintah dalam penyediaan tenaga alih daya, terdaftar dalam SIKaP LKPP, bersedia menerapkan gaji sesuai UMK dan patuh terhadap pembayaran Jaminan Sosial Kesehatan serta Ketenagakerjaan. Untuk personel yang ditempatkan wajib memenuhi persyaratan minimal sebagai berikut : 1. memiliki Surat Keterangan Catatan Kepolisian 2. untuk Security : memiliki sertifikat Gada dan KTA, berpengalaman bekerja sebagai security minimal 2 tahun, bisa mengendarai kendaraan roda 4 jenis matic dan manual, berpenampilan rapih dan sopan 3. Untuk PSTP : memiliki kemampuan komunikasi yang baik, menguasai bahasa Indonesia dan Sunda, memiliki pengetahuan dalam bahasa Inggris (minimal pasif), memiliki kemampuan mengoperasikan komputer, berpenampilan menarik 4. Untuk supir : memiliki SIM A dan pengetahuan standar tentang mesin mobil 5. Untuk petugas kebersihan : bisa menggunakan alat-alat kebersihan, memiliki standar kebersihan dan kerapihan, diutamakan bisa mengendarai kendaraan roda 4 matic dan manual', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 630241);
