INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65904605', 65904605, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Lisensi Software Simulasi Mekanika/Struktur Kelas Enterprise dan Lisensi HPC untuk Laboratorium MMS (Katalog Elektronik/INAPROC)', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 2800000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 (satu) paket', 'Pengadaan lisensi software simulasi mekanika/struktur kelas enterprise (atau setara) beserta lisensi HPC setara 2 (dua) paket untuk mendukung parallel processing/distributed computing, termasuk installer resmi, sertifikat/entitlement lisensi, serta jasa instalasi dan konfigurasi untuk kebutuhan Laboratorium Mekanika Material dan Struktur (MMS)', 'Spesifikasi Teknis Minimum (atau setara): A. Software Simulasi Mekanika/Struktur Kelas Enterprise Kapabilitas minimum: Structural/Mechanical: linear & nonlinear static, contact (linear/nonlinear), joints/constraints, buckling (linear/nonlinear), submodeling & data mapping. Dynamics & Vibrations: modal, harmonic, transient, spectrum, random vibration, cyclic symmetry, rotordynamics (wajib). Acoustics: modal/harmonic/transient acoustics termasuk metode BEM/SEA atau ekuivalen. Thermal: steady-state & transient (conduction, convection, radiation). Advanced materials: user-defined material model (atau ekuivalen), fracture mechanics/crack growth (atau ekuivalen). Composites: layup, failure/delamination (atau ekuivalen), sandwich modeling. Durability/Fatigue: metode SN dan EN (atau ekuivalen). Explicit dynamics: solver explicit untuk dinamika/impact (atau ekuivalen). Optimization: DOE/sensitivity/goal-driven optimization serta topology optimization (atau ekuivalen). Wave hydrodynamics: analisis wave hydrodynamics dan transfer beban ke structural (atau ekuivalen). Ketentuan lisensi & deliverables: Hak penggunaan lisensi sesuai dokumen lisensi yang berlaku, dengan dukungan/maintenance 1 (satu) tahun pertama (TECS atau ekuivalen). Installer resmi, sertifikat/entitlement lisensi, serta jasa instalasi dan konfigurasi. B. Lisensi HPC untuk Software Simulasi Entitlement setara 2 (dua) paket HPC (atau ekuivalen) untuk mendukung parallel processing/distributed computing. Wajib dijelaskan: jumlah core per pack, aturan stacking/penjumlahan, serta batasan penggunaan per solver. Wajib dibuktikan dengan dokumen entitlement/surat prinsipal/distributor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 632077);
