INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65971267', 65971267, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'pengiriman dokumen dari kabupaten/kota ke provinsi', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 28000, 'October 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1 KG, @Rp 28.000 )', '1. pengiriman dokumen dari kabupaten/kota ke provinsi ( 1 KG, @Rp 28.000 );', 'Nama Paket : pengiriman dokumen dari kabupaten/kota ke provinsi Volume : 1 Kg Harga Satuan : @ Rp28.000 ________________________________________ 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pengiriman dokumen kegiatan dari wilayah kabupaten/kota ke kantor provinsi sesuai dengan alamat tujuan yang telah ditentukan. ________________________________________ 2. Spesifikasi Teknis 1. Pengiriman dilakukan terhadap dokumen kegiatan yang telah dikemas oleh pihak pengirim. 2. Dokumen dikirim dalam kondisi aman, rapi, dan terjaga kerahasiaannya selama proses pengiriman. 3. Berat kiriman dihitung berdasarkan total berat dokumen yang dikirim (dalam kilogram). 4. Pengiriman dilakukan menggunakan layanan transportasi darat atau sarana lain yang menjamin dokumen sampai ke tujuan dengan baik. 5. Dokumen diterima oleh petugas yang berwenang di kantor tujuan. ________________________________________ 3. Persyaratan 1. Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. 2. Harga sudah termasuk biaya pengemasan sederhana, transportasi, dan jasa pengiriman. 3. Penyedia bertanggung jawab atas keamanan dan ketepatan pengiriman dokumen sampai ke tujuan. 4. Apabila terjadi kerusakan atau kehilangan dokumen akibat kelalaian penyedia, penyedia bertanggung jawab sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 632617);
