INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62559948', 62559948, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM32 KANTOR IMIGRASI KELAS II TPI TAREMPA', 'Pengadaan Tenaga Alih Daya Petugas Kebersihan pada Kantor Imigrasi Kelas II TPI Tarempa - Kepulauan Riau Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Kepulauan Riau, Kepulauan Anambas (Kab.)', 146480000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '26 OB', 'Pengadaan tenaga alih daya (outsourcing) Petugas Kebersihan mencakup tugas harian seperti menyapu, mengepel, membersihkan toilet, mengelola sampah, serta menjaga kerapian area umum, ruang kerja, kaca, dan eksterior kantor, dengan tujuan utama menciptakan lingkungan yang bersih, sehat, dan nyaman untuk mendukung produktivitas kerja karyawan, diatur dalam SOP khusus oleh perusahaan penyedia jasa (vendor) untuk memastikan standar kebersihan optimal', 'A. Pemeliharaan Area Kerja dan Umum (Indoor) 1) Lantai: Menyapu, mengepel, dan menyedot debu (vacuuming) lantai atau karpet di seluruh area kantor, termasuk ruang kerja, koridor, lobi, dan ruang rapat. 2) Permukaan dan Furnitur: Membersihkan debu dan mengelap meja kerja, kursi, lemari arsip, rak, dan perabotan kantor lainnya. 3) Kaca dan Dinding: Membersihkan jendela kaca, cermin, partisi kaca, dan dinding dari noda atau kotoran. 4) Plafon/Langit-langit: Membersihkan sarang laba-laba atau kotoran lain di area plafon. 5) Pengelolaan Sampah: Mengosongkan tempat sampah secara berkala (harian) dan mengganti kantong sampah di semua area, termasuk area kerja, toilet, dan pantry B. Pemeliharaan Area Khusus (Toilet dan Pantry) 1) Toilet/Kamar Mandi: Membersihkan, mendisinfeksi, dan memastikan kebersihan kloset, urinoir, wastafel, dan area kamar mandi secara menyeluruh. 2) Perlengkapan Toilet: Memeriksa dan mengisi ulang persediaan penting seperti sabun cuci tangan, tisu toilet, tisu pengering, dan pengharum ruangan. 3) Pantry/Dapur: Membersihkan area pantry, wastafel, meja dapur, dan terkadang mencuci atau merapikan peralatan makan dan minum jika diperlukan C. Pemeliharaan Area Luar (Outdoor) 1) Halaman dan Parkir: Menyapu halaman, taman, dan area parkir kendaraan dari kotoran dan sampah. 2) Fasad Bangunan: Membersihkan kaca jendela luar atau papan nama perusahaan jika diperlukan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 635795);
