INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65662965', 65662965, 'analyze_legacy', 'Kota Balikpapan', 'kabkota', 'UPTD-RUMAH SAKIT UMUM DAERAH', 'Pemeliharaan Hepafilter', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Timur, Balikpapan (Kota)', 50000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Kegiatan pemeliharaan Hepafilter dilaksanakan untuk menjaga kinerja sistem filtrasi udara agar tetap optimal dalam menyaring partikel debu, mikroorganisme, dan kontaminan lainnya sesuai standar kebersihan ruangan. Pekerjaan meliputi pemeriksaan kondisi fisik filter dan housing, pengukuran tekanan diferensial (pressure drop), pembersihan area sekitar unit, pengujian kebocoran (leak test) apabila diperlukan, serta penggantian HEPA filter jika sudah melewati masa pakai atau tidak memenuhi standar kinerja. Kegiatan ini juga mencakup pencatatan dan pelaporan hasil pemeriksaan sebagai bagian dari dokumentasi pemeliharaan berkala untuk memastikan sistem HVAC atau cleanroom tetap berfungsi secara efektif dan sesuai persyaratan teknis.', 'Spesifikasi pemeliharaan Hepafilter mencakup pemeriksaan dan pengujian filter dengan efisiensi minimal 99,97% untuk partikel berukuran 0,3 mikron atau sesuai standar yang berlaku, menggunakan alat ukur terkalibrasi. Penggantian filter dilakukan dengan produk yang memiliki spesifikasi teknis setara atau sesuai rekomendasi pabrikan peralatan. Pekerjaan dilaksanakan oleh teknisi yang kompeten dengan memperhatikan prosedur keselamatan kerja dan standar kebersihan ruangan. Setiap tahapan pekerjaan harus didokumentasikan dalam berita acara atau laporan hasil pemeliharaan, termasuk hasil pengukuran tekanan, kondisi filter, serta rekomendasi tindak lanjut guna menjamin mutu udara dan keandalan sistem tetap terjaga.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 638678);
